  {
    "@context": "https://schema.org",
    "@type": "FAQPage",
    "mainEntity": [
      {
        "@type": "Question",
        "name": "What is mining autonomy data collection?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "It's the capture of sensor data and operator demonstrations that train autonomous haul trucks, underground loaders, drill rigs, and inspection robots, recorded in real mine conditions such as dust, darkness, and GPS-denied tunnels."
        }
      },
      {
        "@type": "Question",
        "name": "How do you collect data underground without GPS?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "We capture LiDAR, IMU, and camera data alongside survey control points and reference poses, so localization models can be trained and verified without satellite positioning."
        }
      },
      {
        "@type": "Question",
        "name": "How do you handle dust in mining data?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "We treat dust as a condition to cover, recording across blast cycles and haul road conditions and tagging visibility and lens state on every run."
        }
      },
      {
        "@type": "Question",
        "name": "Can you capture demonstrations from skilled mine operators?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "Yes. Teleoperated demonstrations from experienced operators for loading, drilling, and positioning are recorded with the machine's own states and sensor streams."
        }
      },
      {
        "@type": "Question",
        "name": "Do you work under mine safety rules?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "Yes. All collection runs under the site's safety management system, inductions, and access procedures, scheduled with operations."
        }
      },
      {
        "@type": "Question",
        "name": "Can you scan areas people can't enter?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "Yes. Stopes, voids, and hazardous areas can be scanned with vehicle-mounted, handheld, or drone LiDAR, registered to survey control."
        }
      }
    ]
  }
